  "fig07-3": {
    en: "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 600 304\" role=\"img\" class=\"fig-svg fig-plate\">\n<title>Two ways to lower TDS</title>\n<desc>TDS down, EY unchanged</desc>\n<defs>\n<marker id=\"fig07-3-en-arr\" viewBox=\"0 0 10 10\" refX=\"8\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\">\n<path d=\"M2 1L8 5L2 9\" fill=\"none\" stroke=\"context-stroke\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>\n</marker>\n</defs>\n<g>\n<rect class=\"p-wash s-accent\" x=\"25\" y=\"24\" width=\"260\" height=\"66\" rx=\"12\" stroke-width=\"1\"/>\n<text class=\"p-accent\" x=\"155.0\" y=\"52.0\" font-size=\"15\" text-anchor=\"middle\" font-weight=\"700\">Pour more water through</text>\n<text class=\"p-muted\" x=\"155.0\" y=\"74.0\" font-size=\"13\" text-anchor=\"middle\" font-weight=\"400\">e.g. 1:16 → 1:18</text>\n<line class=\"s-accent\" x1=\"155.0\" y1=\"94.0\" x2=\"155.0\" y2=\"122.0\" stroke-width=\"1.4\" stroke-linecap=\"round\" marker-end=\"url(#fig07-3-en-arr)\"/>\n<rect class=\"p-wash s-accent\" x=\"25\" y=\"128\" width=\"260\" height=\"66\" rx=\"12\" stroke-width=\"1\"/>\n<text class=\"p-accent\" x=\"155.0\" y=\"156.0\" font-size=\"15\" text-anchor=\"middle\" font-weight=\"700\">TDS down, EY up</text>\n<text class=\"p-muted\" x=\"155.0\" y=\"178.0\" font-size=\"13\" text-anchor=\"middle\" font-weight=\"400\">bed extracted further</text>\n<line class=\"s-accent\" x1=\"155.0\" y1=\"198.0\" x2=\"155.0\" y2=\"226.0\" stroke-width=\"1.4\" stroke-linecap=\"round\" marker-end=\"url(#fig07-3-en-arr)\"/>\n<rect class=\"p-wash s-accent\" x=\"25\" y=\"232\" width=\"260\" height=\"66\" rx=\"12\" stroke-width=\"1\"/>\n<text class=\"p-accent\" x=\"155.0\" y=\"260.0\" font-size=\"15\" text-anchor=\"middle\" font-weight=\"700\">Adds the late fraction</text>\n<text class=\"p-muted\" x=\"155.0\" y=\"282.0\" font-size=\"13\" text-anchor=\"middle\" font-weight=\"400\">may bring dryness</text>\n<rect class=\"p-wash s-accent\" x=\"315\" y=\"24\" width=\"260\" height=\"66\" rx=\"12\" stroke-width=\"1\"/>\n<text class=\"p-accent\" x=\"445.0\" y=\"52.0\" font-size=\"15\" text-anchor=\"middle\" font-weight=\"700\">Stop early, dilute in cup</text>\n<text class=\"p-muted\" x=\"445.0\" y=\"74.0\" font-size=\"13\" text-anchor=\"middle\" font-weight=\"400\">brew strong, then bypass</text>\n<line class=\"s-accent\" x1=\"445.0\" y1=\"94.0\" x2=\"445.0\" y2=\"122.0\" stroke-width=\"1.4\" stroke-linecap=\"round\" marker-end=\"url(#fig07-3-en-arr)\"/>\n<rect class=\"p-wash s-accent\" x=\"315\" y=\"128\" width=\"260\" height=\"66\" rx=\"12\" stroke-width=\"1\"/>\n<text class=\"p-accent\" x=\"445.0\" y=\"156.0\" font-size=\"15\" text-anchor=\"middle\" font-weight=\"700\">TDS down, EY unchanged</text>\n<text class=\"p-muted\" x=\"445.0\" y=\"178.0\" font-size=\"13\" text-anchor=\"middle\" font-weight=\"400\">only strength changes</text>\n<line class=\"s-accent\" x1=\"445.0\" y1=\"198.0\" x2=\"445.0\" y2=\"226.0\" stroke-width=\"1.4\" stroke-linecap=\"round\" marker-end=\"url(#fig07-3-en-arr)\"/>\n<rect class=\"p-wash s-accent\" x=\"315\" y=\"232\" width=\"260\" height=\"66\" rx=\"12\" stroke-width=\"1\"/>\n<text class=\"p-accent\" x=\"445.0\" y=\"260.0\" font-size=\"15\" text-anchor=\"middle\" font-weight=\"700\">Nothing more from the bed</text>\n<text class=\"p-muted\" x=\"445.0\" y=\"282.0\" font-size=\"13\" text-anchor=\"middle\" font-weight=\"400\">keeps the early fraction</text>\n</g>\n</svg>",
    vi: "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 600 304\" role=\"img\" class=\"fig-svg fig-plate\">\n<title>Two ways to lower TDS</title>\n<desc>TDS giảm, EY giữ nguyên</desc>\n<defs>\n<marker id=\"fig07-3-vi-arr\" viewBox=\"0 0 10 10\" refX=\"8\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\">\n<path d=\"M2 1L8 5L2 9\" fill=\"none\" stroke=\"context-stroke\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>\n</marker>\n</defs>\n<g>\n<rect class=\"p-wash s-accent\" x=\"25\" y=\"24\" width=\"260\" height=\"66\" rx=\"12\" stroke-width=\"1\"/>\n<text class=\"p-accent\" x=\"155.0\" y=\"52.0\" font-size=\"15\" text-anchor=\"middle\" font-weight=\"700\">Rót thêm nước qua bã</text>\n<text class=\"p-muted\" x=\"155.0\" y=\"74.0\" font-size=\"13\" text-anchor=\"middle\" font-weight=\"400\">ví dụ 1:16 → 1:18</text>\n<line class=\"s-accent\" x1=\"155.0\" y1=\"94.0\" x2=\"155.0\" y2=\"122.0\" stroke-width=\"1.4\" stroke-linecap=\"round\" marker-end=\"url(#fig07-3-vi-arr)\"/>\n<rect class=\"p-wash s-accent\" x=\"25\" y=\"128\" width=\"260\" height=\"66\" rx=\"12\" stroke-width=\"1\"/>\n<text class=\"p-accent\" x=\"155.0\" y=\"156.0\" font-size=\"15\" text-anchor=\"middle\" font-weight=\"700\">TDS giảm, EY tăng</text>\n<text class=\"p-muted\" x=\"155.0\" y=\"178.0\" font-size=\"13\" text-anchor=\"middle\" font-weight=\"400\">bã bị chiết sâu hơn</text>\n<line class=\"s-accent\" x1=\"155.0\" y1=\"198.0\" x2=\"155.0\" y2=\"226.0\" stroke-width=\"1.4\" stroke-linecap=\"round\" marker-end=\"url(#fig07-3-vi-arr)\"/>\n<rect class=\"p-wash s-accent\" x=\"25\" y=\"232\" width=\"260\" height=\"66\" rx=\"12\" stroke-width=\"1\"/>\n<text class=\"p-accent\" x=\"155.0\" y=\"260.0\" font-size=\"15\" text-anchor=\"middle\" font-weight=\"700\">Lấy thêm phần chiết cuối</text>\n<text class=\"p-muted\" x=\"155.0\" y=\"282.0\" font-size=\"13\" text-anchor=\"middle\" font-weight=\"400\">có thể kéo vị khô, chát</text>\n<rect class=\"p-wash s-accent\" x=\"315\" y=\"24\" width=\"260\" height=\"66\" rx=\"12\" stroke-width=\"1\"/>\n<text class=\"p-accent\" x=\"445.0\" y=\"52.0\" font-size=\"15\" text-anchor=\"middle\" font-weight=\"700\">Dừng sớm, thêm nước vào cốc</text>\n<text class=\"p-muted\" x=\"445.0\" y=\"74.0\" font-size=\"13\" text-anchor=\"middle\" font-weight=\"400\">pha cốt rồi pha loãng</text>\n<line class=\"s-accent\" x1=\"445.0\" y1=\"94.0\" x2=\"445.0\" y2=\"122.0\" stroke-width=\"1.4\" stroke-linecap=\"round\" marker-end=\"url(#fig07-3-vi-arr)\"/>\n<rect class=\"p-wash s-accent\" x=\"315\" y=\"128\" width=\"260\" height=\"66\" rx=\"12\" stroke-width=\"1\"/>\n<text class=\"p-accent\" x=\"445.0\" y=\"156.0\" font-size=\"15\" text-anchor=\"middle\" font-weight=\"700\">TDS giảm, EY giữ nguyên</text>\n<text class=\"p-muted\" x=\"445.0\" y=\"178.0\" font-size=\"13\" text-anchor=\"middle\" font-weight=\"400\">chỉ đổi độ đậm</text>\n<line class=\"s-accent\" x1=\"445.0\" y1=\"198.0\" x2=\"445.0\" y2=\"226.0\" stroke-width=\"1.4\" stroke-linecap=\"round\" marker-end=\"url(#fig07-3-vi-arr)\"/>\n<rect class=\"p-wash s-accent\" x=\"315\" y=\"232\" width=\"260\" height=\"66\" rx=\"12\" stroke-width=\"1\"/>\n<text class=\"p-accent\" x=\"445.0\" y=\"260.0\" font-size=\"15\" text-anchor=\"middle\" font-weight=\"700\">Không lấy thêm gì từ bã</text>\n<text class=\"p-muted\" x=\"445.0\" y=\"282.0\" font-size=\"13\" text-anchor=\"middle\" font-weight=\"400\">giữ nguyên phần đầu</text>\n</g>\n</svg>"
  },
